Method.Implementation:
	#dim tSC As %Status=$$$OK
	$$$TRACE("Inside Method PostRequest, timeout " _ ..Adapter.ResponseTimeout)
	// set ..Adapter.ResponseTimeout = 120
	set dataStr = 	pRequest.StringValue
	set pStream = ##class(%Stream.GlobalCharacter).%New()
	Do pStream.Write(dataStr)

	$$$TRACE("Inside Method ProcessHttpsRequest: " _ dataStr)

	Set httprequest=##class(%Net.HttpRequest).%New()

	$$$TRACE("URL: "_..Adapter.URL)
	Set tAdURL = "http://" _ ..Adapter.HTTPServer _ ":8080" _ ..Adapter.URL, tAdURL1=$E(tAdURL)
	$$$TRACE("Location: "_tAdURL)
	// Set httprequest.SSLConfiguration = ..Adapter.SSLConfig
	// $$$TRACE("SSL Config: "_httprequest.SSLConfiguration)
	// Set httprequest.Https="1"

	Set httprequest.ContentType="application/json; charset=utf-8"	
	// do httprequest.SetHeader("apikey", ..ApiKey)
	Do httprequest.EntityBody.Write(dataStr)

	set httprequest.Username = "prvuser"
	set httprequest.Password = "prvuser"
	set httprequest.Timeout = ..Adapter.ResponseTimeout
    set status = httprequest.Post(tAdURL)

    if $$$ISERR(status) {
         do $system.OBJ.DisplayError()
         Quit status
    } else {
        set tHttpResponse=httprequest.HttpResponse
       	$$$TRACE("StatusLine: "_tHttpResponse.StatusLine)  
        $$$TRACE("StatusLine: "_tHttpResponse.Data)
       	// %Stream.GlobalCharacter
       	set stream =   tHttpResponse.Data
       	While 'stream.AtEnd 
       	{ 
       		set outStr = stream.ReadLine(,.sc,.eol)
       		$$$TRACE( outStr) 
       	}
       	set pResponse = ##class(Ens.StringResponse).%New()
       	set pResponse.StringValue = outStr

    }        

	quit tSC
